MODULES=[
 {'slug':'leak-desk','name':'Leak Desk','verb':'Reconcile','headline':'Reconcile the balance before chasing the gap.','short':'Production and billing, brought into the same accounting window.','desc':'Reconcile production and billing volumes before interpreting the difference. Surface period mismatches, missing records and questionable inputs for audit review.','price':'$3,000','unit':'/ utility','output':'Reconciliation worksheet + exception register','inputs':['Production volumes and reporting periods','Billed and unbilled authorized consumption','Meter quality, units and completeness notes'],'steps':[('Align the periods','Compare like accounting windows. A prior-day billing total cannot explain an intraday flow change.'),('Keep the categories separate','Unbilled authorized consumption belongs in non-revenue water; it is not automatically physical leakage.'),('Review the residual','Show the unresolved difference and its source-quality limitations. A utility reviewer owns classification.')],'exception':'An unmatched reporting period blocks a like-for-like comparison. Missing volumes are not zero.','question':'Does the residual prove a leak?','answer':'No. The reconciliation exposes an unresolved balance. Real and apparent losses require additional evidence and utility review.','artifact':'ledger'},
 {'slug':'leak-review','name':'Leak Review','verb':'Observe','headline':'Keep the anomaly in context.','short':'District-meter patterns with the gaps left visible.','desc':'Watch district-meter anomalies alongside flow, pressure and data-quality context. Retain alternative explanations before deciding what deserves attention.','price':'$500','unit':'/ month / district','output':'Timestamped district anomaly watchlist','inputs':['District inlet-flow observations','Pressure samples and quality flags','District boundaries and reference periods'],'steps':[('Name the district','Confirm asset mapping and measurement boundaries before comparing observations.'),('Compare the window','Use a documented reference period and show the observed change without calling it a leak rate.'),('Keep the uncertainty','Missing pressure, demand changes and unresolved calibration remain attached to the watchlist.')],'exception':'Sparse telemetry and an inconsistent district boundary limit interpretation. No live telemetry is connected in this preview.','question':'Is this an automatic leak alert?','answer':'This concept organizes an anomaly for review. Pure leak alerting already exists; local detection performance and differentiation remain unproven.','artifact':'trend'},
 {'slug':'leak-proof','name':'Leak Proof','verb':'Compare','headline':'Bring competing explanations into the same case.','short':'Pressure, acoustic and work-order evidence. One reviewable decision.','desc':'Compare the leak hypothesis with meter and billing alternatives. Keep source timestamps, missing evidence, analyst notes and the reviewer decision in a single case.','price':'$1,500','unit':'/ month / district','output':'Human-reviewed triage packet','inputs':['Pressure and district-flow series','Acoustic observations and meter-quality notes','Asset map, billing window and work-order outcomes'],'steps':[('Attach the sources','Every observation retains its event time, recorded time, quality flag and source reference.'),('Test alternatives','Compare suspected leakage with meter error, demand changes and timing mismatch. Contradicting evidence stays visible.'),('Make the review explicit','A named utility reviewer records a reason and a dated next step. Completing a review never confirms a leak by itself.')],'exception':'In the example case, pressure is incomplete, acoustic evidence is inconclusive and the meter-quality flag is unresolved.','question':'Does “Leak Proof” mean a leak is proven?','answer':'No. Leak Proof is a proposed module name for evidence-led triage. A suspected case requires field evidence before it can be called verified.','artifact':'proof'},
 {'slug':'leak-signal','name':'Leak Signal','verb':'Prepare','headline':'Give the crew a reviewed starting point.','short':'A repair-priority route and work packet with an accountable owner.','desc':'Prepare a draft priority route and reviewed work packet for utility consideration. Keep source context, route constraints, crew ownership and confirmation needs together.','price':'$50','unit':'/ reviewed ticket','output':'Draft route + reviewed ticket packet','inputs':['Human-reviewed triage findings','Asset-map exceptions and access constraints','Crew supervisor, review owner and dated next action'],'steps':[('Review the candidate','Start with an evidence-supported case, including uncertainty and the alternative explanation.'),('Prepare the work packet','List the location context, relevant observations and verification question. Routes are schematic in the demo.'),('Return control to the utility','The utility reviews, authorizes and carries out any field work. Nothing is dispatched by this software.')],'exception':'Crew availability, public tenders, site access and incumbent sensor contracts can constrain the proposed evaluation.','question':'Can this dispatch a crew or operate a valve?','answer':'No. There are no dispatch, pressure-valve, writeback, isolation or excavation controls. Utility operators retain all physical authority.','artifact':'route'},
 {'slug':'leak-report','name':'Leak Report','verb':'Verify','headline':'Keep verification attached to the repair.','short':'Post-repair volumes, comparable windows and evidence for review.','desc':'Compare post-repair volumes with an agreed baseline, record limitations and assemble an evidence report for utility and regulatory review.','price':'$2,000','unit':'/ quarter','output':'Quarterly verification evidence report','inputs':['Field-confirmation and repair records','Pre/post volume windows and demand context','Reviewer annotations and applicable reporting requirements'],'steps':[('Start with field evidence','Keep the confirmation source and repair record distinct from a suspected alert.'),('Check comparability','Align periods and units, document demand changes and show missing observations.'),('Publish the caveats','Export source-linked evidence with reviewer sign-off. Observed differences alone do not prove causal savings.')],'exception':'Quarterly utility/district coverage must be defined in the written scope. Regulatory acceptance and certification are not implied.','question':'Is the report regulator certified?','answer':'No. “Ready for review” means organized against an agreed requirement. The utility and its appropriate reviewers determine suitability.','artifact':'report'}]
SOURCES=[('EPA water-audit guidance','https://www.epa.gov/sites/default/files/2015-04/documents/epa816f13002.pdf','Audit context and real/apparent loss categories; not validation of this demo.'),('FIDO Leak Locate','https://fido.tech/products/leak-locate/','An existing acoustic leak-detection offering; no partnership or superiority claim.'),('Xylem Vue','https://www.xylem.com/en-vn/brand/vue/platform/water-utility-management-software/','An existing utility and water-loss offering; no integration claim.')]
FAQ=[('Is LeakEvidence operating software?','This is a research-stage website and a working, isolated synthetic demo. Production integrations, local detection performance, customer demand and accepted pricing have not been demonstrated.'),('What data does an evaluation need?','A named data owner should review AMI licensing, flow/pressure availability, billing quality and GIS boundaries. Real records require procurement, legal and data-sharing permission before use.'),('How would you establish value?','Blind-rank known repaired leaks and representative false alerts in one district against retrospective utility triage. Pre-register precision at an agreed crew-visit budget, avoided non-leak visits and verification cost.'),('Who owns field decisions?','The utility sponsor, operations director and crew supervisor. LeakEvidence supplies proposed read-only decision support; there are no physical controls, dispatch or automated writeback.'),('Can we test one module first?','Yes. The five modules are separate quotation hypotheses. A first paid evaluation should select one module and a bounded district workflow.'),('Why are there no testimonials?','No customer outcomes or approvals have been supplied. The site shows inspectable synthetic evidence and a pilot scorecard instead of fabricated customer proof.')]
PILOT=[('01','Qualify the district','Identify the budget owner, operator, data owner and crew supervisor. Select one module and discuss a conditional paid scope.'),('02','Agree the permissions','Obtain procurement, legal, data-sharing and AMI licensing permission. Define fields, access, retention and deletion before real records.'),('03','Pre-register the comparison','Agree the historical baseline, evaluator, visit budget K, observation window, positive/negative samples and failure threshold.'),('04','Blind-rank the cases','Hide known outcomes from the ranking reviewer. Compare repaired leaks and representative false alerts at the same visit budget.'),('05','Review the disagreements','Inspect discordant cases, unresolved outcomes, exclusions and verification burden. Do not silently remove difficult negatives.'),('06','Run a paid field validation','Proceed only with signed sponsor and crew-lead approval, paid SOW and authorized AMI/pressure sharing. Utility crews own field activity.'),('07','Make the go/no-go decision','Independently review precommitted criteria. Pause if permissions, safety sign-off, the comparator or representative negatives are missing.')]
